void mainImage(out vec4 O, in vec2 U) {
    vec2 u = U/iResolution.y;
    vec3 p = vec3(u, .0), d=normalize(vec3(u,1.));
    vec3 c = vec3(.0);

    for(float i=0.; i<99.; i++) {
        p += d*.9+(iTime/9.);
        c = abs(mod(p,1.)-1.);
        if(dot(c,c) < .2) break;
    }

    O = vec4(c.r*8.2, c.g*1.9, c.b, .9);
}
